import{_ as a,o as d,c as r,a3 as n}from"./chunks/framework.bvEHUNtb.js";const b=JSON.parse('{"title":"体用生克篇之二：十八占例","description":"以十八类常见事项，练习体用判断的具体展开。","frontmatter":{"title":"体用生克篇之二：十八占例","description":"以十八类常见事项，练习体用判断的具体展开。","category":"学习计划 · 第二阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/ti-yong-sheng-ke/eighteen-divination-cases.md","filePath":"yijing/meihua-yishu/ti-yong-sheng-ke/eighteen-divination-cases.md","lastUpdated":1786982540000}'),e={name:"yijing/meihua-yishu/ti-yong-sheng-ke/eighteen-divination-cases.md"};function o(s,t,i,p,l,h){return d(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="【体用生克篇之二】十八占例" tabindex="-1">【体用生克篇之二】十八占例 <a class="header-anchor" href="#【体用生克篇之二】十八占例" aria-label="Permalink to &quot;【体用生克篇之二】十八占例&quot;">​</a></h1><blockquote><p>本篇是体用总诀的实战展开。十八类事项，每类都有固定的体用判断框架，再加上各类的特殊补充。</p></blockquote><hr><h2 id="📜-原文" tabindex="-1">📜 原文 <a class="header-anchor" href="#📜-原文" aria-label="Permalink to &quot;📜 原文&quot;">​</a></h2><h3 id="天时占第一" tabindex="-1">天时占第一 <a class="header-anchor" href="#天时占第一" aria-label="Permalink to &quot;天时占第一&quot;">​</a></h3><p>凡占天时，不分体用，全观诸卦，详推五行。离多主晴，坎多主雨，坤乃阴晦，干主晴明，震多则春夏雷轰，巽多则四时风烈，艮多则久雨必晴，兑多则不雨亦阴。夏占离多而无坎，则亢旱炎炎。冬占坎多而无离，则雨雪飘飘。</p><p>全观诸卦者，谓互变卦。五行属离属火，主晴；坎为水，主雨；坤为地气，主阴；干为天，主晴明；震为雷，巽为风，秋冬震多无制，亦有非常之雷，有巽佐之，则为风撼雷动之应；艮为山云之气，若雨久，得艮则当止。艮者，止也，亦土克水之义。兑为泽，故不雨亦阴。夫以造化之辨固难测，理数之妙亦可凭，是以干象乎天，四时晴明；坤体乎地，一气惨然。干、坤两同，晴雨时变。坤、艮两并，阴晦不常。卜数有阳有阴，卦象有奇有偶。阴雨阳晴，奇偶暗重。坤为老阴之极，久晴必雨；干为老阳之极，久雨必晴。若逢重坎重离，亦日时晴时雨。坎为水，必雨；离为火，必晴。干、兑为金，秋明晴；坎之水，冬雪凛冽；坤、艮之土，春雨泽，夏火炎蒸。《易》曰：「云从龙，风从虎」。又曰：「艮为云，巽为风。」艮、巽重逢，风云际会，飞沙走石，蔽日藏山，不以四时，不必二用。坎在艮上，布雾兴云，若在兑上，凝霜作雪。干、兑为霜雪雹霰，离火为日电虹霓。离为电，震为雷，重会而雷电俱作。坎为雨，巽为风，相逢而风雨骤兴。震卦重逢，雷惊百里。坎爻迭见，润泽九垓。故卦体之两逢，亦爻象之总断。地天泰，水天需，昏蒙之象。天地否，水地比，黑暗之形。爻纯离，夏必旱，四季皆晴。爻纯坎，冬必寒，四时必雨。久雨不晴，逢艮必止。久晴不雨，得此亦然。又若水火既济、火水未济，四时不测风云；风泽中孚，泽风大过，三冬必然雨雪。水山蹇，山水蒙，百步必须执盖。地风升，风地观，四时不可行船。离在艮上，暮雨朝晴，离互艮宫，暮晴朝雨。巽、坎互离，虹霞乃见，巽、离互坎，造化亦同。又须推测四时，不可执迷一理。震、离为电、为雷，应在夏天，干、兑为霜、为雪，验于冬月。天地之理大矣哉！得斯文者，当敬宝之。</p><h3 id="人事占第二" tabindex="-1">人事占第二 <a class="header-anchor" href="#人事占第二" aria-label="Permalink to &quot;人事占第二&quot;">​</a></h3><p>人事之占，详观体用。体卦为主，用卦为宾。用克体不宜，体克用则吉。用生体有进益之喜，体生用有耗失之患。体用比和，谋为吉利。更详观互卦、变卦，以断吉凶；复究盛衰，以明休咎。</p><p>人事之占，则以全体用总章向决吉凶。若有生体之卦，即看前章八卦中生体之卦有何吉；又看克体之卦有何凶，即看前章克体之卦。无生克，止断本卦。</p><h3 id="家宅占第三" tabindex="-1">家宅占第三 <a class="header-anchor" href="#家宅占第三" aria-label="Permalink to &quot;家宅占第三&quot;">​</a></h3><p>凡占家宅，以体为主，用为家宅。体克用，则家宅多吉，用克体，则家宅多凶。体生用，多耗散，或防失盗之忧。用生体，多进益，或有馈送之喜。体用比和，家宅安稳。如有生体之卦，即以前章人事占断之。</p><h3 id="屋舍占第四" tabindex="-1">屋舍占第四 <a class="header-anchor" href="#屋舍占第四" aria-label="Permalink to &quot;屋舍占第四&quot;">​</a></h3><p>凡占屋舍，以体为主，用为屋舍。体克用，居之吉，用克体，居之凶。体生用，主资财衰退；用生体，则门户兴隆。体用比和，自然安稳。</p><h3 id="婚姻占第五" tabindex="-1">婚姻占第五 <a class="header-anchor" href="#婚姻占第五" aria-label="Permalink to &quot;婚姻占第五&quot;">​</a></h3><p>占婚姻以体为主，用为婚姻。用生体，婚易成，或因婚有得；体生用，婚难成，或因婚有失。体克用，可成但成之迟；用克体，不可成，成亦有害。体用比和，婚姻吉利。</p><p>占婚，体为所占之家，用为所婚之家。体卦旺，则此家门户胜；用卦旺，则彼家资盛。生体，则得婚姻之财；或彼有相就之意；体生，则无嫁奁之资，或此去求婚方谐。若体用比和，则彼此相就，良配无疑。</p><p>干：端正而长<br> 坎：邪淫、黑色、嫉妒、奢侈<br> 艮：色黄多巧<br> 震：美貌难犯<br> 巽：发少稀疏，丑陋心贪<br> 离：短赤色，性不常<br> 坤：貌丑，大腹而黄<br> 兑：高长，语话喜悦，白色</p><h3 id="生产占第六" tabindex="-1">生产占第六 <a class="header-anchor" href="#生产占第六" aria-label="Permalink to &quot;生产占第六&quot;">​</a></h3><p>占生产，以体为母，用为生。体用俱宜乘旺，不宜乘衰。宜相生，不宜相克。体克用不利于子；用克体不利于母。体克用而用卦衰，则子难完；用克体而体卦衰，则母难保。用生体，利于母；体生用，利于子。体用比和，生育顺快。若欲辨其男女，当于前卦审之。阳卦阳爻多者则生男，阴卦阴爻多者生女。阴阳卦爻相生，则察所占左右人之奇偶以证之。如欲决其日辰，则以用卦之气数参决之。所谓卦之气数者，即看何为用卦，于八卦时序之类次之。</p><h3 id="饮食占第七" tabindex="-1">饮食占第七 <a class="header-anchor" href="#饮食占第七" aria-label="Permalink to &quot;饮食占第七&quot;">​</a></h3><p>凡占饮食，以体为主，用为饮食。用生体，饮食必丰；体生用，饮食难就。体克用，则饮食有阻；用克体，饮食必无。体用比和，饮食丰足。又卦中有坎则有酒，有兑则有食。无坎无兑，则皆无。兑、坎生体，酒肉醉饱。欲知所食何物，以饮食推之。欲知席上何人，以互卦人事推之。</p><p>饮食人事类者，即前八卦内万物属类是也。</p><h3 id="求谋占第八" tabindex="-1">求谋占第八 <a class="header-anchor" href="#求谋占第八" aria-label="Permalink to &quot;求谋占第八&quot;">​</a></h3><p>占求谋，以体为主，用为所谋之事。体克用，谋虽可成，但成迟。用克体，求谋不成，谋亦有害。用生体，不谋而成；体生用，多谋少遂。体用比和，求谋称意。</p><h3 id="求名占第九" tabindex="-1">求名占第九 <a class="header-anchor" href="#求名占第九" aria-label="Permalink to &quot;求名占第九&quot;">​</a></h3><p>凡占求名，以体为主，用为名。体克用，名可成，但成迟。用克体，名不可成。体生用，名不可就，或因名有丧。用生体，名易成，或因名有得。体用比和，功名称意。欲知名成之日，生体之卦气详之。欲知职任之处，变卦之方道决之。若无克体之卦，则名易就，止看卦体时序之类，以定日期。若在任占卜，最忌见克体之卦，如卦有克体者，即居官见祸，轻则上司责罚，重则削官退居。其日期，看克体之卦气者，于八卦所属时序类中断之。</p><h3 id="求财占第十" tabindex="-1">求财占第十 <a class="header-anchor" href="#求财占第十" aria-label="Permalink to &quot;求财占第十&quot;">​</a></h3><p>占求财，以体为主，以用为财。体克用，有财；用克体，无财。体生用，财有损耗之忧；用生体，财有进益之喜。体用比和，财利快意。欲知得财之日，生体之卦气定之。欲知破财之日，克体卦气定之。</p><p>又若卦中有体克用之卦，及生体之卦，则有财，此卦气即见财之日。若卦中有克体之卦，及体生用之卦，即破财，此卦气破财之日。</p><h3 id="交易占第十一" tabindex="-1">交易占第十一 <a class="header-anchor" href="#交易占第十一" aria-label="Permalink to &quot;交易占第十一&quot;">​</a></h3><p>占交易，以体为主，用为财。体克用，有财；用克体，不成。体生用，难成，或因交易有失。用生体，即成，成必有财。体用比和，易成。</p><h3 id="出行占第十二" tabindex="-1">出行占第十二 <a class="header-anchor" href="#出行占第十二" aria-label="Permalink to &quot;出行占第十二&quot;">​</a></h3><p>占出行，以体为主，用为所行之应。体克用，可行，所至多得意。用克体，出则有祸。体生用，出行有破耗之失；用生体，有意外之财。体用比和，出行顺快。</p><p>又凡出行，体宜乘旺，诸卦宜生体。体卦干、震多，主动。坤、艮多，不动。巽宜舟行，离宜陆行。坎妨失脱，兑主纷争。</p><h3 id="行人占第十三" tabindex="-1">行人占第十三 <a class="header-anchor" href="#行人占第十三" aria-label="Permalink to &quot;行人占第十三&quot;">​</a></h3><p>占行人，以体为主，用为行人。体克用，行人归迟；用克体，行人不归。体生用，行人未归；用生体，行人即归。体用比和，归期不日矣。</p><p>又以用卦看行人在外之情况。逢生，在外顺快；逢衰受克，在外灾殃。震多不宁，艮多有阻。坎有险难，兑主纷争。</p><h3 id="谒见占第十四" tabindex="-1">谒见占第十四 <a class="header-anchor" href="#谒见占第十四" aria-label="Permalink to &quot;谒见占第十四&quot;">​</a></h3><p>占谒见，以体为主，用为所见之人。体克用，可见；用克体，不见。体生用，难见，见之而无益；用生体，可见，见之且有得。体用比和，欢然相见。</p><h3 id="失物占第十五" tabindex="-1">失物占第十五 <a class="header-anchor" href="#失物占第十五" aria-label="Permalink to &quot;失物占第十五&quot;">​</a></h3><p>占失物，以体为主，用为失物。体克用，可寻迟得；用克体，不可寻。体生用，物难见；用生体，物易寻。体用比和，物不失矣。</p><p>又以变卦为失物之所在。如变是干，则觅于西北或公榭楼阁之所，或金石之傍，或圆器之中，或高亢之地。变卦是坤，则觅于西南方，或田野之所，或仓禀之处，或稼穑之处，或土窖穴藏之所，或瓦器方器之中。震则寻于东方，或山林之所，或丛棘之内，钟鼓之傍，或闹市之地，或大途之所。巽则寻于东南方，或山林之所，或寺观之地，或菜蔬之园，或舟居之间，或木器之内。坎则寻于北方，多藏于水边或溪井沟渠之处，或酒醋之边，或鱼盐之地。离则寻于南方，或疱厨之间，或炉冶之傍，或在明窗，或遗虚室，或在文书之侧，或在烟火之地。艮则寻于东北方，或山林之内，或近路边，或岩石傍，或藏土穴。兑则寻于西方，或居泽畔，或败垣破壁之内，或废井缺沼之中。</p><h3 id="疾病占第十六" tabindex="-1">疾病占第十六 <a class="header-anchor" href="#疾病占第十六" aria-label="Permalink to &quot;疾病占第十六&quot;">​</a></h3><p>凡占疾病，以体为病人，用为病症。体卦宜旺不宜衰，体宜逢生，不宜见克。用宜生体，不宜克体。体克用，病易安；体生用，病难愈。体克用者，勿药有喜；用克体者，虽药无功。若体逢克而乘旺，犹为庶几。体遇克而更衰，断无存日。欲知凶中有救，生体之卦存焉。体生用者，迁延难好；用生体者，即愈。体用比和，疾病易安。若究和平之日，主卦决之。若详危厄之期，克体之卦定之。若论医药之属，当看生体之卦。如离卦生体，宜服热药；坎卦生体，宜服冷药，如艮温补；干、兑凉药是也。</p><p>又有信鬼神之说，虽非《易》道，然不可谓《易》道之不该。姑以理推之。如卦有克体者，即可测其鬼神。干卦克体，主有西北方之神，或兵刀之鬼，或天行时气，或乘正之邪神。坤则西南之神，或旷野之鬼，或连亲之鬼，或水土里社之神，或犯方隅，或无主之祟。震则东方之神，或木下之神，或妖怪百端，或影响时见。巽则东南之鬼，或自缢戕生，或枷锁致命。坎则北方之鬼，或水旁之神，或没溺而亡，或血疾之鬼。离则南方之鬼，或猛勇之神，或犯灶司，或得衍于香火，或焚烧之鬼，或遇热病而亡。艮则东北之神，或是山林之祟，或山魈木客，或土怪石精。兑则西方之神，或阵亡之鬼，或废疾之鬼，或刎颈戕生之鬼。卦中无克体之卦者，不必论之。</p><p>又问干上坤下，占病如何断，尧夫曰：「干上坤下第一爻动，便是生体之义。变为震木，互见巽艮，俱是生成之义，是谓不灾，逢生之日即愈。」</p><p>又问：「第二爻动如何？」曰：「是变为坎水，乃泄体败金之义。金入水乡，互见巽、离，乃为风火扇炉，俱为克体之义。更看占时外应如何，即为焚尸之象，断之死无疑矣。以春夏秋冬四季推之，更见详理。」又曰：「第三爻动，坤变艮土，俱在生体之义，不问互卦，亦断其吉无疑。」又曰：「第四爻动，干变巽木，金木俱有克体之义，互吉亦凶。木有扛尸之义，金为砖椁之推。是必定之推，必定之理。」又曰：「第五爻动，干变离，反能生体，互变俱生体，是其吉无疑。更有吉兆则愈吉。其断明矣。」又曰：「第六爻动，干变兑，则能泄体，互见巽、艮，一凶一吉，其病非死必危。亦宜看兆吉凶，吉则言吉，凶则言凶。此断甚明。余卦皆仿此断，则心易无不验矣。」</p><h3 id="官讼占第十七" tabindex="-1">官讼占第十七 <a class="header-anchor" href="#官讼占第十七" aria-label="Permalink to &quot;官讼占第十七&quot;">​</a></h3><p>占官讼，以体为主，用为对辞之人与官讼之应。体卦宜旺，用卦宜衰。体宜用生，不宜生用。宜生体，不宜克体。是故体克用者，已胜人；用克体者，人胜己。体生用，非为失理，或因官有所丧；用生体，不止得理，或因讼有所得。体用比和，官讼最吉。非但扶持之力，必有主和之义。</p><h3 id="坟墓占第十八" tabindex="-1">坟墓占第十八 <a class="header-anchor" href="#坟墓占第十八" aria-label="Permalink to &quot;坟墓占第十八&quot;">​</a></h3><p>占坟墓以体为主，用为坟墓。体克用，葬之吉；用克体，葬之凶。体生用，葬之主运退；用生体，葬之主兴隆，有荫益后嗣。体用比和，乃为吉地。大宜葬，葬之吉昌。</p><p>上为用体之诀，始发十八章占例，以示后学之法则。然庶务之多，岂止十八占而已乎！然此十八占，乃大事之切要者，占者以类而推之可也。</p><hr><h2 id="🔤-注音与字词" tabindex="-1">🔤 注音与字词 <a class="header-anchor" href="#🔤-注音与字词" aria-label="Permalink to &quot;🔤 注音与字词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字词</th><th>注音</th><th>释义</th></tr></thead><tbody><tr><td>亢旱</td><td>kàng hàn</td><td>极度干旱</td></tr><tr><td>九垓</td><td>jiǔ gāi</td><td>九重天，泛指极广大的范围</td></tr><tr><td>昏蒙</td><td>hūn méng</td><td>天色昏暗不明</td></tr><tr><td>执盖</td><td>zhí gài</td><td>撑伞，指雨大</td></tr><tr><td>霰</td><td>xiàn</td><td>雪珠，小冰粒</td></tr><tr><td>休咎</td><td>xiū jiù</td><td>吉凶，休为吉，咎为凶</td></tr><tr><td>嫁奁</td><td>jià lián</td><td>嫁妆</td></tr><tr><td>戕生</td><td>qiāng shēng</td><td>自杀，伤害生命</td></tr><tr><td>山魈</td><td>shān xiāo</td><td>传说中山中的独脚鬼怪</td></tr><tr><td>木客</td><td>mù kè</td><td>传说中山林中的精怪</td></tr><tr><td>砖椁</td><td>zhuān guǒ</td><td>砖砌的棺椁</td></tr><tr><td>扛尸</td><td>gāng shī</td><td>抬运尸体</td></tr><tr><td>勿药有喜</td><td>wù yào yǒu xǐ</td><td>不需用药自然痊愈，出自《易·无妄》</td></tr><tr><td>庶几</td><td>shù jī</td><td>尚有希望，差不多</td></tr><tr><td>对辞</td><td>duì cí</td><td>对方的诉词，打官司的对方</td></tr><tr><td>荫益后嗣</td><td>yìn yì hòu sì</td><td>庇荫后代子孙</td></tr><tr><td>疱厨</td><td>páo chú</td><td>厨房</td></tr><tr><td>稼穑</td><td>jià sè</td><td>农耕，种植收获</td></tr><tr><td>仓禀</td><td>cāng lǐn</td><td>粮仓</td></tr><tr><td>刎颈</td><td>wěn jǐng</td><td>割喉自杀</td></tr></tbody></table><hr><h2 id="📖-白话译文摘要" tabindex="-1">📖 白话译文摘要 <a class="header-anchor" href="#📖-白话译文摘要" aria-label="Permalink to &quot;📖 白话译文摘要&quot;">​</a></h2><blockquote><p>十八占各有原文，此处只摘译各占的<strong>核心判断原则</strong>，原文已完整保留于上。</p></blockquote><p><strong>天时占</strong>：不分体用，全观诸卦（含互变）。离多晴，坎多雨，坤阴晦，乾晴明，震雷，巽风，艮止雨，兑阴。结合四时推断，不可执一。</p><p><strong>人事占</strong>：体用为主，互变辅助，参前章生克体之卦断吉凶。</p><p><strong>家宅占</strong>：体克用吉，用克体凶；用生体进益，体生用耗散。</p><p><strong>屋舍占</strong>：同家宅逻辑，体克用居之吉，用克体居之凶。</p><p><strong>婚姻占</strong>：用生体易成有得，体克用可成但迟，用克体不可成。另附八卦配人形貌。</p><p><strong>生产占</strong>：体为母，用为生。体克用不利子，用克体不利母。阳爻多生男，阴爻多生女。</p><p><strong>饮食占</strong>：用生体饮食丰，用克体饮食无。有坎则有酒，有兑则有食。</p><p><strong>求谋占</strong>：用生体不谋而成，体生用多谋少遂，用克体谋有害。</p><p><strong>求名占</strong>：用生体名易成，用克体名不成。变卦方道定职任之处，克体卦气定祸期。</p><p><strong>求财占</strong>：体克用有财，用克体无财。生体卦气为得财之日，克体卦气为破财之日。</p><p><strong>交易占</strong>：用生体即成有财，用克体不成，体克用有财。</p><p><strong>出行占</strong>：体克用可行得意，用克体出则有祸。乾震多主动，坤艮多不动。</p><p><strong>行人占</strong>：用生体行人即归，用克体行人不归。用卦看行人在外状况。</p><p><strong>谒见占</strong>：体克用可见，用克体不见。用生体可见且有得。</p><p><strong>失物占</strong>：用生体物易寻，用克体不可寻。变卦定失物方位。</p><p><strong>疾病占</strong>：体克用病易安，用克体虽药无功。体旺逢克犹可，体衰逢克必危。生体卦定医药，克体卦定危期。另附鬼神推断与天地否卦六爻动占例。</p><p><strong>官讼占</strong>：体克用己胜，用克体人胜。体用比和主和解。</p><p><strong>坟墓占</strong>：体克用葬之吉，用生体兴隆荫后。</p><hr><h2 id="🧭-义理解析" tabindex="-1">🧭 义理解析 <a class="header-anchor" href="#🧭-义理解析" aria-label="Permalink to &quot;🧭 义理解析&quot;">​</a></h2><h3 id="一、天时占-唯一不分体用的占法" tabindex="-1">一、天时占：唯一不分体用的占法 <a class="header-anchor" href="#一、天时占-唯一不分体用的占法" aria-label="Permalink to &quot;一、天时占：唯一不分体用的占法&quot;">​</a></h3><p>十八占中，<strong>天时占是唯一一个不分体用、全观诸卦的占法</strong>。</p><p>原因很清楚：天时是客观的自然现象，没有「我方」与「对方」之分。天下雨，不是针对谁的，是整体的气象状态。所以要全观本卦·互卦·变卦，综合判断。</p><p>天时占的核心逻辑：</p><table tabindex="0"><thead><tr><th>卦</th><th>天时象</th><th>特殊说明</th></tr></thead><tbody><tr><td>乾</td><td>晴明</td><td>老阳之极，久雨必晴</td></tr><tr><td>坤</td><td>阴晦</td><td>老阴之极，久晴必雨</td></tr><tr><td>震</td><td>雷</td><td>秋冬震多无制，亦有非常之雷</td></tr><tr><td>巽</td><td>风</td><td>四时风烈</td></tr><tr><td>坎</td><td>雨·雪</td><td>冬坎多，雨雪飘飘</td></tr><tr><td>离</td><td>晴·日·电</td><td>夏离多无坎，亢旱炎炎</td></tr><tr><td>艮</td><td>止雨·云雾</td><td>久雨逢艮必止，土克水之义</td></tr><tr><td>兑</td><td>阴·泽</td><td>不雨亦阴</td></tr></tbody></table><p><strong>特殊卦象天时对照</strong>：</p><table tabindex="0"><thead><tr><th>卦象组合</th><th>天时</th></tr></thead><tbody><tr><td>艮巽重逢</td><td>风云际会，飞沙走石</td></tr><tr><td>坎在艮上</td><td>布雾兴云</td></tr><tr><td>坎在兑上</td><td>凝霜作雪</td></tr><tr><td>离震重会</td><td>雷电俱作</td></tr><tr><td>坎巽相逢</td><td>风雨骤兴</td></tr><tr><td>水火既济·火水未济</td><td>四时不测风云</td></tr><tr><td>风泽中孚·泽风大过</td><td>三冬必然雨雪</td></tr><tr><td>水山蹇·山水蒙</td><td>大雨，百步须执盖</td></tr><tr><td>地风升·风地观</td><td>四时不可行船</td></tr><tr><td>离在艮上</td><td>暮雨朝晴</td></tr><tr><td>离互艮宫</td><td>暮晴朝雨</td></tr></tbody></table><p>末句「又须推测四时，不可执迷一理」——震离为雷电应在夏，乾兑为霜雪验于冬。同一卦，四时不同，象的显现不同。这是「论理诀」在天时占中的具体体现。</p><h3 id="二、十七占的体用通用框架" tabindex="-1">二、十七占的体用通用框架 <a class="header-anchor" href="#二、十七占的体用通用框架" aria-label="Permalink to &quot;二、十七占的体用通用框架&quot;">​</a></h3><p>除天时占外，其余十七占都遵循同一个体用框架，可以用一张总表来理解：</p><table tabindex="0"><thead><tr><th>体用关系</th><th>通用判断</th><th>特殊说明</th></tr></thead><tbody><tr><td>用生体</td><td>吉·顺·有得</td><td>婚：易成；求谋：不谋而成；疾病：即愈</td></tr><tr><td>体用比和</td><td>百事顺遂</td><td>官讼比和主和解</td></tr><tr><td>体克用</td><td>吉·可成（或迟）</td><td>婚：可成但迟；疾病：勿药有喜</td></tr><tr><td>体生用</td><td>耗·难成</td><td>婚：难成有失；疾病：迁延难好</td></tr><tr><td>用克体</td><td>凶·不成</td><td>疾病：虽药无功；行人：不归</td></tr></tbody></table><p>这个框架是体用总诀的直接应用，十七占只是把「体」和「用」的具体含义换了：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>家宅占：体=我，用=家宅</span></span>
<span class="line"><span>婚姻占：体=我方，用=婚方</span></span>
<span class="line"><span>生产占：体=母，用=子</span></span>
<span class="line"><span>疾病占：体=病人，用=病症</span></span>
<span class="line"><span>官讼占：体=我，用=对方</span></span>
<span class="line"><span>……</span></span></code></pre></div><p>框架不变，含义随事项而换。</p><h3 id="三、各占的特殊补充" tabindex="-1">三、各占的特殊补充 <a class="header-anchor" href="#三、各占的特殊补充" aria-label="Permalink to &quot;三、各占的特殊补充&quot;">​</a></h3><p>每一占在通用框架之外，都有独特的补充判断，这些才是各占的精华：</p><p><strong>婚姻占</strong>：附八卦配人形貌</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾：端正而长</span></span>
<span class="line"><span>坎：邪淫黑色嫉妒奢侈</span></span>
<span class="line"><span>艮：色黄多巧</span></span>
<span class="line"><span>震：美貌难犯</span></span>
<span class="line"><span>巽：发少稀疏，丑陋心贪</span></span>
<span class="line"><span>离：短赤色，性不常</span></span>
<span class="line"><span>坤：貌丑大腹而黄</span></span>
<span class="line"><span>兑：高长喜悦白色</span></span></code></pre></div><p>这是通过卦象来判断婚配对象的外貌性情，是象的直接应用。</p><p><strong>饮食占</strong>：有坎则有酒，有兑则有食——这是两个特殊的象：坎为水为酒，兑为口为食。无坎无兑，则酒食皆无。</p><p><strong>失物占</strong>：变卦定方位——这是变卦的一个独特用法，不是看吉凶，而是看方向。变卦的方位即失物所在之方。</p><p><strong>求名占</strong>：变卦方道定职任之处——与失物占同理，变卦的方位决定将来任职的方向。</p><p><strong>疾病占</strong>：最为详尽，有三个特殊补充：</p><ol><li><strong>医药</strong>：生体之卦定用药冷热——离生体用热药，坎生体用冷药，艮温补，乾兑凉药</li><li><strong>鬼神</strong>：克体之卦定鬼神方位——虽非易道，但「不可谓易道之不该」，邵雍的态度是存而不论，以理推之</li><li><strong>六爻动占例</strong>：以天地否（乾上坤下）为例，逐爻分析，示范如何逐爻断病</li></ol><p><strong>天地否六爻动占例</strong>（疾病）：</p><table tabindex="0"><thead><tr><th>动爻</th><th>变化</th><th>互卦</th><th>断语</th></tr></thead><tbody><tr><td>初爻动</td><td>坤变震木</td><td>互见巽艮</td><td>俱生体（金），逢生之日即愈</td></tr><tr><td>二爻动</td><td>乾变坎水</td><td>互见巽离</td><td>金入水乡泄体，风火扇炉克体，死无疑</td></tr><tr><td>三爻动</td><td>坤变艮土</td><td>—</td><td>俱生体，吉无疑</td></tr><tr><td>四爻动</td><td>乾变巽木</td><td>—</td><td>金木俱克体，互吉亦凶，必死</td></tr><tr><td>五爻动</td><td>乾变离火</td><td>互变俱生体</td><td>离生金体，互变俱生，吉无疑</td></tr><tr><td>六爻动</td><td>乾变兑金</td><td>互见巽艮</td><td>兑泄体，巽凶艮吉，非死必危</td></tr></tbody></table><p>这个例子是全书最完整的逐爻断法示范，展示了「体用·互变·外应」三者综合运用的方式。</p><h3 id="四、官讼占的特殊性" tabindex="-1">四、官讼占的特殊性 <a class="header-anchor" href="#四、官讼占的特殊性" aria-label="Permalink to &quot;四、官讼占的特殊性&quot;">​</a></h3><p>官讼占有一句特别值得注意：</p><blockquote><p>「体用比和，官讼最吉。非但扶持之力，必有主和之义。」</p></blockquote><p>其他占的「比和」只是「顺遂」，官讼的比和却是「主和」——双方势均力敌，最终走向和解。这是象的逻辑：两个相同的力量相遇，没有胜负，自然趋于平衡。</p><hr><h2 id="🌀-象的感悟" tabindex="-1">🌀 象的感悟 <a class="header-anchor" href="#🌀-象的感悟" aria-label="Permalink to &quot;🌀 象的感悟&quot;">​</a></h2><h3 id="天时占-天地自有其象" tabindex="-1">天时占：天地自有其象 <a class="header-anchor" href="#天时占-天地自有其象" aria-label="Permalink to &quot;天时占：天地自有其象&quot;">​</a></h3><p>天时占不分体用，是因为<strong>天地不以人的立场为立场</strong>。</p><p>雨就是雨，晴就是晴。坎多则雨，离多则晴——这不是对谁好或对谁坏，是天地自身的状态。</p><p>这一占提醒我们：有些事情，不是「对我有利还是不利」的问题，而是「当下的状态是什么」的问题。学会全观，不只从自己的体卦出发，有时候需要退出来，看整个卦的气场。</p><h3 id="疾病占-体旺则生-体衰则危" tabindex="-1">疾病占：体旺则生，体衰则危 <a class="header-anchor" href="#疾病占-体旺则生-体衰则危" aria-label="Permalink to &quot;疾病占：体旺则生，体衰则危&quot;">​</a></h3><p>疾病占里有一句话，是全书最直接的生死判断：</p><blockquote><p>若体逢克而乘旺，犹为庶几。体遇克而更衰，断无存日。</p></blockquote><p>体旺，即使被克，还有一线生机。体衰，再被克，则无救。</p><p>这不只是占病的逻辑，是一切事情的底层逻辑：<strong>自身的力量是根本</strong>。外部的压力（克）固然重要，但自身的状态（旺衰）才是决定性的。</p><p>体旺，则逢凶化吉有可能。体衰，则小凶也可能致命。</p><p>这让我想到：占卜的意义，不只是预测结果，更是提醒我们<strong>养旺自己的体</strong>——无论是身体、精力，还是一件事情的根基。</p><h3 id="失物占-变卦是方向" tabindex="-1">失物占：变卦是方向 <a class="header-anchor" href="#失物占-变卦是方向" aria-label="Permalink to &quot;失物占：变卦是方向&quot;">​</a></h3><p>失物占里，变卦不用来判断吉凶，而是用来定方位——这是变卦的一个很有意思的用法。</p><p>变卦是「事之终」，失物的终点就是它最终所在的地方。乾变则在西北高处，坎变则在北方水边，离变则在南方明亮处……</p><p>象在这里变成了<strong>空间的指向</strong>。这让我感受到：象不只是时间维度的（先吉后凶），也是空间维度的（在哪里）。</p><h3 id="「庶务之多-岂止十八占」" tabindex="-1">「庶务之多，岂止十八占」 <a class="header-anchor" href="#「庶务之多-岂止十八占」" aria-label="Permalink to &quot;「庶务之多，岂止十八占」&quot;">​</a></h3><p>末句与篇之三末句「占者宜各以其类而推之耳」呼应。</p><p>邵雍一再说：这只是示例，不是全部。十八占是「大事之切要者」，但生活中的事情远不止十八类。</p><p><strong>以类推之</strong>——这才是真正的学习目标。不是背会十八个答案，而是理解体用生克的逻辑，然后遇到任何事情都能推类而断。</p><hr><h2 id="📌-小结" tabindex="-1">📌 小结 <a class="header-anchor" href="#📌-小结" aria-label="Permalink to &quot;📌 小结&quot;">​</a></h2><p><strong>本节关键词</strong></p><ul><li>天时占：唯一不分体用，全观诸卦，结合四时</li><li>十七占通用框架：用生体吉·比和顺·体克用可·体生用耗·用克体凶</li><li>各占「体」「用」的具体含义随事项而变</li><li>失物·求名：变卦定方位（不只定吉凶）</li><li>饮食：坎=酒，兑=食，两个特殊象</li><li>疾病：体旺逢克犹可，体衰逢克必危；生体卦定医药</li><li>官讼：比和主和解</li><li>疾病六爻动例：体用·互变·外应三者综合运用的完整示范</li></ul><p><strong>规律提炼</strong></p><ol><li>十八占的框架完全一致，只是「体」「用」的具体所指不同——掌握框架，万占可推</li><li>变卦的用途不只是判断吉凶，还可以定方位（失物·求名）</li><li>体的旺衰是根本，比体用关系更基础——体旺则有救，体衰则无力</li><li>天时占「全观诸卦」的思路，提示我们有时需要退出体用框架，看整体气场</li><li>各占的特殊补充（婚姻形貌·饮食坎兑·疾病医药鬼神）是象的细化应用，不是额外规则，是同一套象的延伸</li></ol><p><strong>与前文呼应</strong></p><ul><li>体用总诀（篇之一）的五种生克关系，在十八占中逐一落地</li><li>篇之三万物属类详表（婚姻·饮食·疾病·出行等各项），正是本篇各占断卦时的查询依据</li><li>「以类推之」再次出现——与篇之三末句、篇之一「圆机不可执」一脉相承</li></ul><hr><h2 id="❓-存疑" tabindex="-1">❓ 存疑 <a class="header-anchor" href="#❓-存疑" aria-label="Permalink to &quot;❓ 存疑&quot;">​</a></h2><blockquote><p><strong>❓****-011</strong>：婚姻占中八卦配人形貌，「坎：邪淫、黑色、嫉妒、奢侈」，「巽：发少稀疏，丑陋心贪」，「坤：貌丑，大腹而黄」——这些描述明显带有负面评价，与篇之三坎「外示以柔，内序以利」、巽「柔和」的描述有出入。是否因为婚姻占的语境（相人）与一般卦象描述（论事）不同，导致侧重点不同？待后续章节印证。</p></blockquote><blockquote><p><strong>❓****-012</strong>：疾病占六爻动例中，「第二爻动，乾变坎水，互见巽离，乃为风火扇炉，俱为克体之义」——乾为金体，坎水泄金（金生水，体生用，耗），巽木克坤（？），离火克金（克体）。但原文说「俱为克体之义」，巽木克金之说存疑（木不克金，金克木），此处「风火扇炉」似为取象而非五行生克，即巽风助离火，火势更盛克金。是否如此理解？标记待印证。</p></blockquote><blockquote><p><strong>❓****-013</strong>：失物占「变卦为失物之所在」，与求名占「变卦之方道决职任之处」——两者都用变卦定方位。但体用总诀说「变乃末后之期」（时间），这里却用作空间方位。变卦究竟是时间还是空间的指向？还是两者都可以，视占事类型而定？待卷三「变卦式」章节印证。</p></blockquote>`,144)])])}const g=a(e,[["render",o]]);export{b as __pageData,g as default};
